	0 if a's precedence is more than b operator
	1 otherwise
	"""
def checkOperatorPrecedence(a: Any, b: Any) -> object {
    check = {};
    check['('] = 3;
    check['^'] = 2;
    check['*'] = 2;
    check['/'] = 2;
    check['-'] = 1;
    check['+'] = 1;
    if (check[a] <= check[b]) {
        return 1;
    } else {
        return 0;
    }
}

